-- ----------------------------
-- 人才培养方案智能优化 v3：导入逐行业抓取结果（非计算机行业）
-- 数据源：08-行业对照表/逐行业抓取结果_20261027_184638.csv
-- 可重复执行：先清理 source 标记数据与 V3 专业课程
-- ----------------------------
SET NAMES utf8mb4;

-- 1. 历史 IT 岗位行业统一为「互联网/AI」
UPDATE talent_job_posting SET industry = '互联网/AI' WHERE industry IS NULL OR industry = '' OR industry = '信息技术';

-- 2. 清理上次行业对照表导入结果（保证幂等）
DELETE FROM talent_job_skill WHERE posting_id IN (SELECT id FROM talent_job_posting WHERE source = '行业对照表2026-10-27');
DELETE FROM talent_job_posting WHERE source = '行业对照表2026-10-27';

-- 3. 导入 66 条行业岗位（快照 batch_date = ''）

-- 4. 技能标签（按行业 + 职位名称关联刚插入的岗位）
CREATE TEMPORARY TABLE tmp_v3_skill (industry varchar(50), title varchar(200), skill_name varchar(100));
SELECT p.id, '', t.skill_name, '业务技能'
FROM tmp_v3_skill t
JOIN talent_job_posting p ON p.source = '行业对照表2026-10-27' AND p.industry = t.industry AND p.job_title = t.title;
DROP TEMPORARY TABLE tmp_v3_skill;

-- 5. 清理并重建 V3 专业与课程
DELETE FROM talent_major_course WHERE major_id IN (SELECT id FROM talent_major WHERE major_code LIKE 'V3-%')
   OR course_id IN (SELECT id FROM talent_course WHERE course_code LIKE 'V3-%');
DELETE FROM talent_course WHERE course_code LIKE 'V3-%';
DELETE FROM talent_major WHERE major_code LIKE 'V3-%';

-- 6. 非 IT 专业（14 个）

-- 7. 非 IT 课程（70 门）

-- 8. 专业-课程关联（仅关联本专业课程）
SELECT m.id, c.id FROM talent_major m
JOIN talent_course c ON c.job_family = m.job_family AND c.course_code LIKE 'V3-%'
WHERE m.major_code LIKE 'V3-%';

SELECT 'postings', COUNT(*) FROM talent_job_posting WHERE source = '行业对照表2026-10-27';
SELECT 'skills', COUNT(*) FROM talent_job_skill s JOIN talent_job_posting p ON p.id = s.posting_id WHERE p.source = '行业对照表2026-10-27';
SELECT 'majors', COUNT(*) FROM talent_major WHERE major_code LIKE 'V3-%';
SELECT 'courses', COUNT(*) FROM talent_course WHERE course_code LIKE 'V3-%';
