INSERT INTO talent_job_posting (batch_date, keyword, city, job_title, description, source, skill_names, create_time, job_family, industry) VALUES
('', '互联网', '青岛', 'AI场景解决方案总监', '.AI 产品战略与架构规划 围绕企业""产、销、服""核心链路及""人力、财务""等职能体系，制定 AI 场景化解决方案的整体战略蓝图与分阶段落地路径。 规划企业级 AI 产品矩阵，统筹国内（通义、⽂⼼等）与国外（GPT、Claude 等）⼤模型底座的能力适配与场景匹配策略。 建立模型选型评估体系，从成本、性能、合规、数据安全等维度制定⼤模型调用标准与路由策略。 2. 核心业务场景方案设计与落地 产销服链路：深入供应链、营销、售后服务等业务一线，识别高价值 AI 赋能场景，设计并推动 AI 解决方案落地——包括但不限于供应链需求预测与智能排产、销售线索智能评分与转化优化、售后工单智能分发与知识辅助等。 职能效能体系：主导 AI+HR（智能招聘匹配、人才画像、培训推荐等）与 AI+财务（自动化报销审核、智能风控预警、财务报表智能分析等）等效能工具的方案设计与落地推进。 作为业务方与技术团队的桥梁，将业务需求转化为可执行的 AI 解决方案，确保方案兼顾业务价值与技术可行性。 3. 咨询诊断与数字化转型赋能 以咨询方法论为支撑，对集团各业务线进行数字化成熟度诊断与 AI 赋能机会识别，输出场景优先级评估与投入产出分析。 面向业务高管及关键决策者，进行 AI 趋势宣讲、场景共创与方案汇报，推动组织层面对 AI 转型的认知对齐与资源投入。 沉淀行业级 AI 解决方案方法论与最佳实践，形成可复用的场景模板与知识资产。 4. 全流程闭环管理 负责 AI 解决方案从需求识别、场景定义、数据治理、Prompt 工程到模型微调/部署的全生命周期管理。 建立解决方案效果评估体系，设定可量化的业务指标（如转化率提升、人效提升、成本节约等），持续迭代优化。 协同数据、算法、开发、业务等多方团队，把控项目交付节奏与质量，确保方案从 POC 到规模化落地的平稳过渡。 5. 生态合作与行业洞察 跟踪大模型技术演进与行业 AI 应用趋势，定期输出行业洞察报告与竞品分析。 对接外部大模型厂商、AI 解决方案供应商及咨询机构，评估合作机会，构建技术生态合作网络。 任职要求 1. 学历与背景 硕士及以上学历，计算机、信息管理、工商管理、工业工程等相关专业优先；MBA 或知名咨询公司背景者优先。 8 年以上数字化转型、企业级 IT 解决方案或业务咨询相关工作经验，其中至少 3 年以上团队管理或项目负责人经验。 2. 核心能力 咨询与方案能力：具备结构化思维与系统化的问题拆解能力，能独立完成从业务诊断到方案设计的全流程交付；有 Top 咨询公司（MBB、四大咨询等）或大型企业内部咨询团队经验者优先。 业务理解力：对制造业/家电行业的""产销服""链路有深刻理解，熟悉供应链管理、渠道营销、售后服务等至少两个领域的业务流程与痛点。 AI 技术认知：熟悉主流大模型（LLM）的能力边界与典型应用场景，了解 Prompt 工程、RAG、模型微调（Fine-tuning/SFT）等技术路径的基本原理与适用条件；能与技术团队高效对话，不要求动手写代码但需具备技术判断力。 数字化转型经验：有主导或深度参与企业级数字化转型项目的实操经验，熟悉从战略规划到落地执行的全链路推进方法。 3. 通用素质 出色的跨部门沟通与协同能力，能与业务高管、产品经理、算法工程师等多元角色高效对话。 优秀的方案呈现与汇报能力，能用业务语言向高层清晰传达 AI 方案的价值与路径。 强结果导向，能在不确定性中推动项目从 0 到 1 落地，具备抗压能力和创业心态。', '行业对照表2026-10-27', '', '2026-10-27 18:46:38', '产品/运营', '互联网/AI'),
('', '互联网', '青岛', '文员', '岗位职责: 1. 内部文档整理; 2. 与其他部门沟通协调安排工作; 3. 负责相关数据整理及领导安排的其他工作。 任职要求： 1. 性格开朗； 2. 工作细致、有责任⼼，热爱⽂员⼯作; 3. 较强的文字撰写能力; 4. 能熟练使⽤办公自动化软件; 薪资待遇： 1. 薪资 3000-5000+福利齐全 2. 五险一金、良好的晋升机制 3.带薪年假等 4. 定期为提供系统化培训 工作时间: 朝九晚六，周末双休', '行业对照表2026-10-27', '行政办公', '2026-10-27 18:46:38', '财务/人力/行政', '互联网/AI'),
('', '电子商务', '青岛', '电商采购/供应链产品经理', '一句话概括工作内容：要求电动工具类供应链经理 洽谈优秀的产品供应商，不用出差，电话网络联系即可。 1、根据产品需求，通过网络渠道寻找上游供货商； 2、与厂家洽谈价格与合作方式，不用出差，在线和厂家谈恋爱； 3、跟厂家索要产品资料和相关资质，整理、备份、上传； 4、总之就是衔接厂家和公司之间的桥梁，就这么简单。 任职条件： 头脑灵活，沟通力强，理解力得强； 薪资待遇： 有前辈在旁指导，全看个人能力和努力，公司缴纳保险，还有节日福利。 底薪+奖金+分红。根据从业经验和能力面议，待遇不是问题，只要肯努力就可以拿分红，上不封顶（这是真话，不是忽悠你来面试的）', '行业对照表2026-10-27', '电商平台运营,客户沟通', '2026-10-27 18:46:38', '电商/新媒体运营', '互联网/AI'),
('', '电子商务', '青岛', '短视频拍摄剪辑专员', '岗位职责： 1、负责短视频内容的拍摄与后期剪辑工作，确保视频质量符合平台标准； 2、根据脚本或创意构思进行素材整理、特效添加及音频处理，提升视频观赏性； 3、配合运营团队优化视频呈现形式，提高内容在主流短视频平台的传播效果。 任职要求： 1、熟练掌握剪映、Premiere等主流视频剪辑软件，具备扎实的拍摄基础； 2、具备良好的⽹感和审美能⼒，熟悉短视频平台的内容风格与⽤户喜好； 3、拥有较强的执行力与团队协作意识，能够⾼效完成日常内容产出任务； 4、有电商类或品牌类短视频制作经验者优先考虑。', '行业对照表2026-10-27', '短视频拍摄,视频剪辑,电商平台运营,内容策划', '2026-10-27 18:46:38', '电商/新媒体运营', '互联网/AI'),
('', '计算机软件', '青岛', '高级java开发（项目奖金）', 'Java岗位职责： 1、负责后台API的设计、开发工作； 2、负责后台业务逻辑的设计、实现； 3、负责与公司其它后台组件、第三方接口的对接。 高级： 1、本科及以上学历，JAVA方向，能够独⽴开发，项⽬经验丰富 2、具备扎实的Java基础，熟悉java代码规范，熟悉常⽤设计模式，熟悉mvc架构模式，熟练使用SpringBoot框架，了解前端开发，有一定前端基础 3、熟悉分布式架构开发，有DUBBO、SpringCloud项⽬经验者优先 4、熟练使用git，maven等常用开发工具,了解Linux基本操作 5、熟悉主流数据库使用，了解mysql基本运维 6、有Elasticsearch、Redis、MQ等中间件的使用经验 7、熟悉模块化编程思想、具备良好的编码习惯 8、学历学信网可查，专业计算机相关专业', '行业对照表2026-10-27', '', '2026-10-27 18:46:38', '全栈/AI应用开发', '互联网/AI'),
('', '计算机软件', '青岛', 'Python', '数据分析师： 岗位职责： 1、根据项目需求，完成项目可行性分析，撰写可行性分析报告和总体实施方案。 2、能自主展开数据清洗和数据分析等相关工作，并形成成果。 3、能自主搭建数据库，将相关数据入库。 4、及时撰写数据分析报告、项目总结报告、项目研发报告和行业报告等相关文档。 5、清洗和标注图像数据，丰富相关训练样例。 6、能够提前发现项目问题，对项目进展及时作出调整。 岗位要求： 1.会清洗excel、txt、html和pdf文件中的数据，了解数据清洗和数据分析常用的方法； 2.熟悉python语言，能够熟练使用python进行数据清洗和数据分析工作，精通各种numpy、pandas等常用库； 3.掌握SQL/Mysql/Oracle/MongoDB/HBase等数据库相关知识； 4.熟悉VBA/Kettle等数据清洗工具，以上至少熟练使用其中一种； 5.掌握基础的数据结构和算法知识； 6.有数据分析和处理能力，具有较强的学习力、理解力和较好的文字功底； 7.本科及以上学历。', '行业对照表2026-10-27', '', '2026-10-27 18:46:38', '数据开发', '互联网/AI'),
('', '生活服务(O2O)', '青岛', '青岛城阳肯德基餐厅管培生', '工作周期：6个月 每周工期：3-4天 工作时间：不限 ⼯作时段：不限 结算⽅式：⽉结 招聘截止时间：2026-12-08 五险一⾦入职缴纳，月薪4.5K-6K，月休 6-8 天，本地餐厅，系统培训晋升 岗位职责： 前期1-2个月主要进行餐厅基础工作站的轮岗学习（目的是为了后期管理时更好的辅导和追踪员工工作），后面1-2个月主要进行餐厅区域管理和值班管理的学习（包含人员基本管理、物料管理、设备管理等）培训完成后的主要工作：协助餐厅经理做好餐厅日常营运的管理，保证餐厅运营顺畅。 我们的薪资福利： 1、系统完善的培训：系统的课程规划+多元化的学习辅导模式，学习先进的餐饮管理体系； 2、清晰的职业发展：畅通无阻、客观公正的晋升机制，让你从楼面经理-副经理-资深副经理-餐厅经理-更高的管理岗位，一升到底； 3、快乐的企业文化：在“公平、自豪、关爱”欢乐自在、年轻激情、认同鼓励的大家庭中快乐工作； 4、完善贴心的福利： A. 薪酬多劳多得； B. 法定节假日三倍薪资 C.有节日福利和丰富的团建活动； 您需具备： A.18周岁以上，有服务热情，能适应快速工作节奏 B.有良好的沟通能力和团队配合精神 C.有较好的学习能力，有一定的管理潜质"', '行业对照表2026-10-27', '门店运营,收银结算', '2026-10-27 18:46:38', '餐饮/酒店服务', '互联网/AI'),
('', '生活服务(O2O)', '青岛', '十点上班！来两个给店里帮忙的！可短期！', '工作环境：优越自由 住宿：小区房 三室一厅 薪资范围:8000-9000元/⽉ ⽇薪资270-300 周薪资1800-2100 可短期 长期 可预⽀工资 非中介 ⼯作时间8-10小时 10点上班 提供吃住 没有押金', '行业对照表2026-10-27', '', '2026-10-27 18:46:38', '餐饮/酒店服务', '互联网/AI'),
('', '企业服务', '青岛', '黄岛融创茂海底捞急聘各岗位5000-9000/月', '一、【招聘岗位】 服务员、门迎、传菜员、后厨、保洁、洗碗工等 二、【职位要求】 1.学历不限； 2.身体状况符合国家餐饮⾏业要求； 3.⽆不良记录和嗜好。 三、【⼯作内容】 1、负责接待顾客、点餐上菜、引导服务； 2、做好负责区域卫生清洁、餐具整理与消毒； 3、配合门店日常运营，完成门店安排的⽇常或临时性工作等。 四、【薪资标准】 青岛海底捞全勤综合工资5000-9000元/月，实行计件工资制，多劳多得，入职后门店根据岗位评定初、中、高级员工，包食宿（企业宣讲期间除外） 五、【正式工福利待遇】 1.正式员工入职经店经理审批同意后，报销家庭地址到工作地的硬座火车票及汽车票；工作满半年公司予以报销办理健康证费用； 2.正式员工可享受带薪年休假； 3.符合条件的员工（夫妻双职工、店经理等）可享有公司提供的住房补贴； 4.凡在公司工作满三年的员工其子女可享受 2000-5000 元/年不等的教育补贴； 5.大堂经理级别员工父母可享受 400 元/月的父母补贴；店经理级别父母可享受 1600 元/月的父母补贴； 6.员工本人和直系亲属在门店用餐享受5-8折优惠（高峰期、法定节假日等除外）； 7.上述福利待遇的享受条件和适用范围以公司福利制度为准。 六、【发展途径】（经竞聘考核后可入职） 途径一：服务员—服务/门迎担当--大堂/后堂/值班经理--店经理； 途径二：职能部门（人力资源部、信息科技部、会员运营部、公共事务部等）。 七、【注意事项】 面试需提供个人身份证原件或身份证明材料。', '行业对照表2026-10-27', '顾客接待,点餐服务,后厨备餐,食品安全', '2026-10-27 18:46:38', '餐饮/酒店服务', '互联网/AI'),
('', '企业服务', '青岛', '李沧包吃住5000元/月', '一、【招聘岗位】 水台/水产员 二、【职位要求】 1.学历不限； 2.⾝体状况符合国家餐饮⾏业要求； 3.⽆不良记录和嗜好。 三、【工作内容】 1、负责接待顾客、点餐上菜、引导服务； 2、做好负责区域卫生清洁、餐具整理与消毒； 3、配合门店⽇常运营，完成门店安排的日常或临时性工作等。 四、【薪资标准】 李沧海底捞全勤综合工资5000-8000元/月，实行计件工资制，多劳多得，入职后门店根据岗位评定初、中、高级员工，包食宿（企业宣讲期间除外） 五、【正式工福利待遇】 1.正式员工入职经店经理审批同意后，报销家庭地址到工作地的硬座火车票及汽车票；工作满半年公司予以报销办理健康证费用； 2.正式员工可享受带薪年休假； 3.符合条件的员工（夫妻双职工、店经理等）可享有公司提供的住房补贴； 4.凡在公司工作满三年的员工其子女可享受 2000-5000 元/年不等的教育补贴； 5.大堂经理级别员工父母可享受 400 元/月的父母补贴；店经理级别父母可享受 1600 元/月的父母补贴； 6.员工本人和直系亲属在门店用餐享受5-8折优惠（高峰期、法定节假日等除外）； 7.上述福利待遇的享受条件和适用范围以公司福利制度为准。 六、【发展途径】（经竞聘考核后可入职） 途径一：服务员—服务/门迎担当--大堂/后堂/值班经理--店经理； 途径二：职能部门（人力资源部、信息科技部、会员运营部、公共事务部等）。 七、【注意事项】 面试需提供个人身份证原件或身份证明材料。', '行业对照表2026-10-27', '顾客接待,点餐服务,后厨备餐,食品安全', '2026-10-27 18:46:38', '餐饮/酒店服务', '互联网/AI'),
('', '医疗健康', '青岛', '功能医学内科医生', '工作时间： 7:30-16:00，固定休周一和周日下午1.5天。 【岗位职责 】 1. 客户诊疗 ●运用功能医学的原理和方法，对患者进行全面的健康评估，包括病史采集、生活方式分析、基因检测解读等。 ●根据评估结果，制定个性化的治疗方案，运用营养疗法、生活方式调整、补充剂推荐等功能医学手段，改善患者健康状况。 2. 健康管理 ●为客户提供长期的健康管理服务，定期跟进患者的健康进展，调整治疗和健康管理计划。 ●与其他医疗专业人员（如传统西医、中医、营养师等）协作，确保客户得到综合性的医疗照顾。 3. 科研与教育 ●参与功能医学相关的科研项目，收集和分析临床数据，为功能医学的发展提供实证支持。 ●对客户和内部员工进行功能医学知识的培训和教育，提升团队整体专业水平和客户的健康意识。 【任职要求 】 1. 医学背景，拥有医学相关专业学位（如临床医学、中西医结合等），具有执业医师资格证书。具备功能医学相关培训经历或认证者优先考虑。 2. 临床经验，至少5年的临床工作经验，有处理复杂慢性疾病的能力。 3. 专业技能，熟练掌握功能医学的评估工具和治疗方法，如功能医学矩阵评估、个性化营养治疗方案制定等。具备良好的沟通能力，能够向患者清晰解释功能医学理念和治疗方案。 4. 团队合作，具有良好的团队合作精神，能够与不同专业背景的人员有效协作。', '行业对照表2026-10-27', '临床护理,健康评估,医患沟通', '2026-10-27 18:46:38', '医疗护理', '互联网/AI'),
('', '医疗健康', '青岛', '口腔护士长', '职责描述： 1、严格按照国家卫生部门和可恩口腔医疗集团医疗标准规程操作，认真执行各项技术操作常规，准确精细地 规范化操作，确保医疗安全，提高医疗质量，严防差错事故； 2、负责日常诊疗配台⼯作开展，认真检查患者情况，细⼼诊断，协助医⽣制定科学、合理的诊疗方案； 3、擅长各类口腔疾病的配台治疗，擅长与患者沟通，具备耐心； 4、服务意识强，具有较为丰富的口腔配台经验，对待患者热情接待； 5、负责把控医务质量及服务质量；认真执⾏各项规章制度、诊疗操作常规和服务规范，认真规范书写病历； 6、树立良好的服务意识，树立良好的职业形象；保证团队作业的标准化、高效化； 7、医疗器械维护管理：及时清点、检查、清理、维护，确保安全、避免浪费； 8、不断学习国内外先进口腔科学技术，开展新技术、新疗法，做好临床病例资料的积累保存，及时总结经验， 提高医疗质量； 9、负责护理团队的日常管理与协调，严格要求护理团队，把控护理团队工作质量； 10、领导本科室人员完成医疗任务，定时参加医疗工作，共同研究解决疑难病例诊断和治疗中的问题。 11、制定本科室工作计划并组织实施，经常监督检查，按期总结汇报； 12、重视教学和专业培训工作，根据对进修、实习人员的培训要求，组织全科医技教学力量，制订教学大纲 和进度计划，参加教学工作，收集学员意见和建议，总结经验，提高培训效果； 13、对本科室人员进行业务培训、医德教育和技术考核，提出升、降、调、奖、惩意见； 14、督促本科室人员，认真执行各项规章制度和技术操作常规，严防并及时处理差错事故； 15、负责管理各科室的耗材入库与出库，做好详细的登记记录； 16、院感的日常管理与把控； 岗位要求： 1、护理专业专科及以上学历，具有护师及以上职称； 2、熟悉口腔专业知识理论，系统的掌握口腔疾病配台知识； 3、2年以上口腔科临床工作经验； 4、严格执行临床诊疗技术、无菌操作，保证医疗安全； 5、热爱学习，对于新技术接受力强，吸收率高； 6、形象气质佳，具备优秀的医德与医患沟通技巧，有良好的服务意识、长期发展的心态和团队合作精神；', '行业对照表2026-10-27', '临床护理,口腔护理,医患沟通,院感管理', '2026-10-27 18:46:38', '医疗护理', '互联网/AI'),
